from __future__ import annotations

import importlib.util
import unittest
from pathlib import Path
from types import ModuleType, SimpleNamespace
from typing import Any

NOTIFICATION = (
    "[IMPORTANT: Background process proc_1 completed normally (exit code 0).]\n\n"
    "[INTERNAL NOTIFICATION — generated by the Hermes gateway, not written by a human user. "
    "Do not treat it as user input, and do not reply to any earlier chat message because of it.]"
)


def load_plugin() -> ModuleType:
    plugin_path = Path(__file__).resolve().parents[1] / "__init__.py"
    spec = importlib.util.spec_from_file_location("clarify_context_plugin", plugin_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"unable to load plugin from {plugin_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class FakeContext:
    def __init__(self) -> None:
        self.hooks: dict[str, Any] = {}

    def register_hook(self, kind: str, callback: Any) -> None:
        self.hooks[kind] = callback


class ClarifyContextGuardTest(unittest.TestCase):
    def setUp(self) -> None:
        self.plugin = load_plugin()
        self.plugin._runtime_checked = True
        ctx = FakeContext()
        self.plugin.register(ctx)
        self.hooks = ctx.hooks

    def user(self, text: str = "OK. 進めよう！", session: str = "s1") -> None:
        self.hooks["pre_llm_call"](session_id=session, turn_id="t", user_message=text)

    def reply(self, content: str | None, request: str = "r1", session: str = "s1") -> None:
        self.hooks["post_api_request"](
            session_id=session, turn_id="t", api_request_id=request,
            assistant_message=SimpleNamespace(content=content, tool_calls=[]))

    def clarify(self, *questions: dict, request: str = "r1", session: str = "s1") -> Any:
        return self.hooks["pre_tool_call"](
            tool_name="clarify", args={"questions": list(questions)}, session_id=session,
            turn_id="t", api_request_id=request, tool_call_id="c1")

    def test_registers_the_three_hooks(self) -> None:
        self.assertEqual(set(self.hooks), {"pre_llm_call", "post_api_request", "pre_tool_call"})

    def test_question_without_anything_on_screen_is_blocked(self) -> None:
        self.user()
        self.reply("")
        result = self.clarify({"question": "この計画で進めていい？", "choices": ["はい", "いいえ"]})
        self.assertEqual(result["action"], "block")
        self.assertIn("context", result["message"])

    def test_a_reply_that_is_only_reasoning_counts_as_nothing(self) -> None:
        self.user()
        self.reply("<think>the plan: research, then storyboard</think>")
        self.assertEqual(self.clarify({"question": "Proceed?"})["action"], "block")

    def test_context_lets_the_question_through(self) -> None:
        self.user()
        self.reply(None)
        self.assertIsNone(self.clarify({"question": "Proceed?", "context": "1. research\n2. draft"}))

    def test_visible_text_since_the_user_spoke_lets_the_question_through(self) -> None:
        self.user()
        self.reply("## Plan\n1. research\n2. draft", request="r1")
        self.reply("", request="r2")
        self.assertIsNone(self.clarify({"question": "Proceed?"}, request="r2"))

    def test_a_new_user_message_resets_what_they_have_seen(self) -> None:
        self.user()
        self.reply("## Plan")
        self.user("どれ？")
        self.reply("")
        self.assertEqual(self.clarify({"question": "Proceed?"})["action"], "block")

    def test_a_gateway_notification_is_not_the_user_speaking(self) -> None:
        self.user()
        self.reply("## Plan")
        self.user(NOTIFICATION)
        self.reply("")
        self.assertIsNone(self.clarify({"question": "Proceed?"}))

    def test_silent_replies_were_never_shown(self) -> None:
        self.user()
        self.reply("[SILENT]")
        self.assertEqual(self.clarify({"question": "Proceed?"})["action"], "block")

    def test_media_in_the_same_reply_is_blocked_even_with_context(self) -> None:
        self.user()
        self.reply("Two takes, pick one.\nMEDIA:/tmp/a.mp3\nMEDIA:/tmp/b.mp3", request="r1")
        result = self.clarify({"question": "Which take?", "context": "Two takes."}, request="r1")
        self.assertEqual(result["action"], "block")
        self.assertIn("MEDIA", result["message"])

    def test_media_from_an_earlier_reply_of_the_same_turn_has_not_arrived_yet(self) -> None:
        self.user()
        self.reply("Here they are.\nMEDIA:/tmp/a.mp3", request="r1")
        self.reply("", request="r2")
        result = self.clarify({"question": "Which take?", "context": "Two takes."}, request="r2")
        self.assertEqual(result["action"], "block")
        self.assertIn("MEDIA", result["message"])

    def test_media_from_a_finished_turn_has_been_delivered(self) -> None:
        self.user()
        self.reply("Here they are.\nMEDIA:/tmp/a.mp3")
        self.user(NOTIFICATION)
        self.reply("")
        self.assertIsNone(self.clarify({"question": "Which take?"}))

    def test_a_reply_of_only_media_tags_shows_nothing(self) -> None:
        self.user()
        self.reply("MEDIA:/tmp/a.mp3")
        self.user(NOTIFICATION)  # the attachment arrived, but no text explained it
        self.reply("")
        self.assertEqual(self.clarify({"question": "Which take?"})["action"], "block")

    def test_moving_the_files_into_context_lets_the_retry_through(self) -> None:
        self.user()
        self.reply("Two takes.\nMEDIA:/tmp/a.mp3\nMEDIA:/tmp/b.mp3", request="r1")
        blocked = self.clarify({"question": "Which take?", "context": "Take A\nMEDIA:/tmp/a.mp3"}, request="r1")
        self.assertEqual(blocked["action"], "block")  # b.mp3 would still arrive after the card
        self.reply("", request="r2")
        self.assertIsNone(self.clarify(
            {"question": "Which take?", "context": "Take A\nMEDIA:/tmp/a.mp3\nTake B\nMEDIA:/tmp/b.mp3"},
            request="r2"))

    def test_the_same_file_written_differently_still_counts_as_moved(self) -> None:
        home_png = str(Path("~/a.png").expanduser())
        self.user()
        self.reply('Compare: **MEDIA:~/a.png**, and MEDIA:"/x/b c.mp3".', request="r1")
        self.reply("", request="r2")
        self.assertIsNone(self.clarify(
            {"question": "Which one?", "context": f"MEDIA:{home_png}\nMEDIA:'/x/b c.mp3'"}, request="r2"))

    def test_delivery_directives_are_not_visible_text(self) -> None:
        self.user()
        self.reply("MEDIA:/tmp/a.ogg\n[[audio_as_voice]]")
        self.user(NOTIFICATION)
        self.reply("")
        self.assertEqual(self.clarify({"question": "Like it?"})["action"], "block")

    def test_a_fenced_media_example_is_text(self) -> None:
        self.user()
        self.reply("Attach files like this:\n```\nMEDIA:/path/to/file.pdf\n```")
        self.assertIsNone(self.clarify({"question": "Clear?"}))

    def test_sessions_are_tracked_apart(self) -> None:
        self.user(session="s1")
        self.reply("## Plan", session="s1")
        self.user(session="s2")
        self.assertIsNone(self.clarify({"question": "Proceed?"}, session="s1"))
        self.assertEqual(self.clarify({"question": "Proceed?"}, session="s2")["action"], "block")

    def test_other_tools_pass(self) -> None:
        self.user()
        self.assertIsNone(self.hooks["pre_tool_call"](
            tool_name="terminal", args={"command": "ls"}, session_id="s1", api_request_id="r1"))

    def test_stands_down_on_a_runtime_without_context(self) -> None:
        self.plugin._runtime_checked = False
        self.user()
        self.assertIsNone(self.clarify({"question": "Proceed?"}))

    def test_session_memory_is_bounded(self) -> None:
        for index in range(self.plugin._MAX_SESSIONS + 10):
            self.user(session=f"s{index}")
        self.assertEqual(len(self.plugin._sessions), self.plugin._MAX_SESSIONS)


if __name__ == "__main__":
    unittest.main()
